def P(txt, style='BodyX'):
    return Paragraph(txt, styles[style])
def bullet(txt):
    return Paragraph('&bull; ' + txt, styles['BulletX'])
def code(txt):
    return P(txt.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('\n','<br/>'), 'CodeX')
def grid(rows, widths, header=True):
    cooked=[]
    for ri,row in enumerate(rows):
        cooked.append([Paragraph(str(x), ParagraphStyle('cell'+str(ri), parent=styles['SmallX'], fontName='Helvetica-Bold' if header and ri==0 else 'Helvetica', textColor=colors.white if header and ri==0 else INK, leading=10)) for x in row])
    t=Table(cooked, colWidths=widths, repeatRows=1 if header else 0, hAlign='LEFT')
    commands=[('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('GRID',(0,0),(-1,-1),0.35,LINE)]
    if header: commands += [('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F6F9FB')])]
    t.setStyle(TableStyle(commands)); return t

def page(canvas, doc):
    canvas.saveState(); w,h=A4
    if doc.page > 1:
        canvas.setFillColor(TEAL); canvas.rect(0,h-7*mm,w,7*mm,fill=1,stroke=0)
        canvas.setFillColor(MUTED); canvas.setFont('Helvetica',7.5)
        canvas.drawString(18*mm,10*mm,'E-Commerce Customer Behavior Analytics | Project guide')
        canvas.drawRightString(w-18*mm,10*mm,f'{doc.page}')
        canvas.setStrokeColor(LINE); canvas.line(18*mm,14*mm,w-18*mm,14*mm)
    canvas.restoreState()

